// Live values are server supplied. Explicitly marked design samples are isolated from checkout.
const rows=[['total','Total Premium (inclusive of 25% commission)'],['discount','Discount'],['net','Nett Premium'],['sst','SST 8%'],['stampDuty','Stamp Duty'],['final','Final Premium']];
export function money(value){return typeof value==='number'&&Number.isFinite(value)&&value>=0?'RM '+value.toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2}):'RM —';}
const available=q=>q&&rows.every(([key])=>typeof q[key]==='number'&&Number.isFinite(q[key])&&q[key]>=0);
export function premiumSummary(quote=null){quote=available(quote)?quote:null;return `<div class="premium-summary"><div class="premium-price"><strong>${money(quote?.final)}</strong><span>${quote?'Inclusive of SST &amp; Stamp Duty':'Not yet calculated'}</span></div><button type="button" class="link-btn premium-breakdown-trigger" data-action="premium-breakdown" aria-haspopup="dialog" aria-controls="modal">Premium breakdown <span aria-hidden="true">⌃</span></button></div>`;}
export function premiumBreakdown(quote=null){quote=available(quote)?quote:null;return `${Array.isArray(quote?.items)?'<dl class="premium-items">'+quote.items.map(item=>'<div><dt>'+String(item.label).replace(/[&<>"']/g,c=>'&#'+c.charCodeAt(0)+';')+'</dt><dd>'+money(item.amount)+'</dd></div>').join('')+'</dl>':''}<table class="breakdown premium-breakdown-table"><caption class="sr-only">Premium breakdown in Malaysian ringgit</caption><tbody>${rows.map(([key,label])=>`<tr${key==='final'?' class="premium-final"':''}><th scope="row">${label}</th><td>${money(quote?.[key])}</td></tr>`).join('')}</tbody></table>${quote?'':'<p class="hint premium-unavailable">Your premium will appear here when quotation services are available. Payment is not available yet.</p>'}`;}
